fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    if numbers.is_empty() {
        return Vec::new();
    }
    
    let mut result = Vec::with_capacity(numbers.len() * 2 - 1);
    
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num);
        
        // Don't add delimiter after the last element
        if i < numbers.len() - 1 {
            result.push(delim);
        }
    }
    
    result
}